import { createSysone, classifier, predicate } from '@sysone-help/sysone';
import { vercel } from '@sysone-help/sysone/providers/vercel';

const client = createSysone({ provider: vercel(), model: 'typesafe-ai/jev' });
const team = classifier({
  billing: 'Payments, invoices and refunds',
  support: 'Bugs, outages and technical help',
  other: 'Anything outside the listed categories',
});
const needsReply = predicate('Does this message need a reply?');

export async function route(message: string, sys = client) {
  // Independent questions, one shared input, one request.
  const { answers } = await sys.evaluate(message, { team, needsReply });
  if (answers.needsReply.probability <= 0.2) return 'archive';
  if (answers.needsReply.probability < 0.8) return 'review';
  return answers.team.choice; // 'billing' | 'support' | 'other'
}

filter:
import { createSysone } from '@sysone-help/sysone';
import { vercel } from '@sysone-help/sysone/providers/vercel';

const client = createSysone({ provider: vercel(), model: 'typesafe-ai/jev' });
type Chunk = { id: string; text: string };

export async function relevantContext(question: string, chunks: Chunk[], sys = client) {
  // One request per chunk, at most four running at once.
  const { yes, uncertain } = await sys.partition(
    chunks,
    'Does the passage help answer the question?',
    { select: (chunk) => ({ question, passage: chunk.text }), concurrency: 4 },
  );
  return { context: yes, review: uncertain }; // Original objects, in input order.
}

rank:
import { createSysone, rubric } from '@sysone-help/sysone';
import { vercel } from '@sysone-help/sysone/providers/vercel';

const client = createSysone({ provider: vercel(), model: 'typesafe-ai/jev' });
const relevance = rubric('How useful is the passage for answering the question?', [
  'Unrelated: offers no useful information',
  'Partial: relevant but cannot answer the question alone',
  'Direct: contains enough information to answer the question',
]);

export async function rankPassages(question: string, passages: string[], sys = client) {
  // One request per passage. This ranks independently, not pairwise.
  return sys.rank(passages, relevance, {
    select: (passage) => ({ question, passage }),
    concurrency: 4,
  }); // [{ item, score, answer, metadata }], highest first.
}
